package com.collabboard.config;
import com.collabboard.security.AuthRateLimitFilter;import com.collabboard.security.JwtCookieFilter;import org.springframework.context.annotation.*;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.web.SecurityFilterChain;import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;
@Configuration public class SecurityConfig {@Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder(12);}@Bean SecurityFilterChain filterChain(HttpSecurity http,JwtCookieFilter jwt,AuthRateLimitFilter rateLimit)throws Exception{return http.csrf(c->c.disable()).cors(c->{}).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).exceptionHandling(e->e.authenticationEntryPoint((req,res,ex)->res.sendError(401))).authorizeHttpRequests(a->a.requestMatchers("/api/auth/signup","/api/auth/login","/api/auth/password/forgot","/api/auth/password/reset","/ws","/ws/**","/error").permitAll().anyRequest().authenticated()).addFilterBefore(jwt,UsernamePasswordAuthenticationFilter.class).addFilterBefore(rateLimit,UsernamePasswordAuthenticationFilter.class).build();}}

